        list.add(v("opportunity", "/ˌɒp.əˈtjuː.nɪ.ti/", "/ˌɑː.pɚˈtuː.nɪ.t̬i/", "noun", "cơ hội", "hoàn cảnh thuận lợi để làm điều gì đó", "This job offers a great opportunity to develop your skills.", "Công việc này mang lại cơ hội tuyệt vời để phát triển kỹ năng.", "great opportunity, miss an opportunity, take an opportunity", "Không nói 'chance' và 'opportunity' hoàn toàn giống nhau; opportunity thường lớn hơn, ít ngẫu nhiên hơn.", "A2", "Future"));

